<script setup lang="ts">
/**
 * TagInput.Chip: one value, with its remove button, playing its exit when it is removed.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tag-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { useTemplateRef, watch } from 'vue'

import { Icon } from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/tag-input.module.css'

export interface TagInputChipProps {
  tag: string
  /**
   * False once the value is removed, while the chip plays its exit.
   */
  open: boolean
  /**
   * The chip joined after the list’s first render, so it plays its enter.
   */
  appear: boolean
  /**
   * A duplicate entry matched this chip.
   */
  flash: boolean
  disabled: boolean
  /**
   * The remove button’s accessible name.
   */
  removeLabel: string
}

defineOptions({ name: 'TagInputChip', inheritAttrs: false })

const props = defineProps<TagInputChipProps>()
const emit = defineEmits<{ remove: []; keyDown: [event: KeyboardEvent]; done: [] }>()
const chip = useTemplateRef<HTMLElement>('chip')
const present = usePresence(() => props.open, chip, 'taginput.chip', {
  get appear() {
    return props.appear
  },
  reflow: 'taginput.reflow',
})
const effect1 = () => {
  present.value || emit('done')
}
watch(() => present.value, effect1, { flush: 'post' })
</script>

<template>
  <li
    ref="chip"
    :class="styles.chip"
    :data-removing="!open ? '' : undefined"
    :data-flash="flash ? '' : undefined"
  >
    <!-- label -->
    <span :class="styles.label">
      {{ tag }}
    </span>
    <!-- remove -->
    <button
      v-if="!disabled"
      :class="styles.remove"
      type="button"
      :aria-label="removeLabel"
      @click="emit('remove')"
      @keydown="emit('keyDown', $event)"
    >
      <Icon name="close" size="sm" />
    </button>
  </li>
</template>
